<?php
namespace davvag_events;

require_once dirname(__DIR__,2).'/lib/bootstrap.php';

final class CheckinService extends Service {
    public function getAttendees($req,$res) { return $this->run($req,$res,function($in){$e=Store::load($in['eventId']??'');Identity::authorize($e,Identity::actor(),'checkin');$needle=mb_strtolower(Support::text($in['name']??'',180));$out=[];foreach($e['guests'] as $g)if($needle===''||mb_strpos(mb_strtolower($g['name']),$needle)!==false)$out[]=['id'=>$g['id'],'name'=>$g['name'],'rsvp'=>$g['rsvp'],'seats'=>Seating::lookup($e,[$g['id']])];return ['attendees'=>array_slice($out,0,100)];}); }
    public function postScan($req,$res) { return $this->run($req,$res,function($in){$a=Identity::actor();$id=$in['eventId']??'';$secret=Support::text($in['credential']??'',200,true);
        for($try=0;$try<4;$try++){try{$r=Store::mutate($id,$a,'checkin',function(&$e)use($a,$secret){return Admission::checkin($e,$secret,$a['id']);});return $r['value'];}catch(Fault $f){if($f->reason!=='CONFLICT')throw $f;}}Support::fail('CONFLICT','Another scan is processing. Retry this code.',409);},true); }
    public function postIssueAdmission($req,$res) { return $this->run($req,$res,function($in){$r=Store::mutate($in['eventId']??'',Identity::actor(),'guests',function(&$e)use($in){if(!empty($e['draft']['modules']['tickets']))Support::fail('TICKET_REQUIRED','Use the ticket issuance path for this event.');$g=$e['guests'][Domain::guestIndex($e,$in['guestId']??'')];if($g['rsvp']!=='Attending')Support::fail('RSVP','Confirm attendance before issuing admission.');foreach($e['tokens'] as &$t)if($t['scope']==='admission'&&$t['reference']===$g['id'])$t['revoked']=true;unset($t);$secret=Domain::issue($e,'admission',$g['id']);return ['credential'=>$secret,'url'=>Support::baseUrl().'#/app/davvag-events/tickets?eventId='.$e['id'].'&admission='.$secret];});return $r['value'];},true); }
    public function postManual($req,$res) { return $this->run($req,$res,function($in){$a=Identity::actor();$r=Store::mutate($in['eventId']??'',$a,'checkin',function(&$e)use($in,$a){Domain::window($e,'checkin');$reason=Support::text($in['reason']??'',500,true);$g=$e['guests'][Domain::guestIndex($e,$in['guestId']??'')];$admission=$g['id'];if(!empty($e['draft']['modules']['tickets'])){$admission=null;foreach($e['tickets'] as $t)if($t['guestId']===$g['id']&&$t['status']==='issued')$admission=$t['id'];if(!$admission)Support::fail('TICKET_REQUIRED','No valid admission was issued.',409);}if($g['rsvp']!=='Attending')Support::fail('RSVP','This attendee has not confirmed.',409);foreach($e['checkins'] as $c)if($c['admission']===$admission&&empty($c['reversedAt']))return ['status'=>'already_used','name'=>$g['name']];$e['checkins'][]=['id'=>Support::id(),'admission'=>$admission,'guestId'=>$g['id'],'actor'=>$a['id'],'at'=>Support::now(),'reason'=>$reason,'reversedAt'=>null];return ['status'=>'valid','name'=>$g['name']];});return $r['value'];},true); }
    public function postReverse($req,$res) { return $this->run($req,$res,function($in){$a=Identity::actor();$r=Store::mutate($in['eventId']??'',$a,'owner',function(&$e)use($in,$a){$reason=Support::text($in['reason']??'',500,true);foreach($e['checkins'] as &$c)if($c['id']===($in['checkinId']??'')){$c['reversedAt']=Support::now();$c['reversedBy']=$a['id'];$c['reversalReason']=$reason;return ['reversed'=>true];}Support::fail('CHECKIN','Check-in not found.',404);});return $r['value'];},true); }
}
